              <Table.Body>
                {comparison.map((row) => (
                  <Table.Row key={row.feature} bg="bg.panel">
                    <Table.Cell as="th" scope="row" fontWeight="medium" textAlign="start">
                      {row.feature}
                    </Table.Cell>
                    <Table.Cell textAlign="center">
                      <Cell value={row.free} />
                    </Table.Cell>
                    <Table.Cell textAlign="center" bg="brand.subtle">
                      <Cell value={row.team} />
                    </Table.Cell>
                    <Table.Cell textAlign="center">
                      <Cell value={row.business} />
                    </Table.Cell>
                  </Table.Row>
                ))}
              </Table.Body>
            </Table.Root>
          </Table.ScrollArea>
        </Container>
      </Box>

      <Box as="section" aria-labelledby="faq-title">
        <Container maxW="3xl" py={{ base: "12", md: "20" }}>
          <Heading
            as="h2"
            id="faq-title"
            fontFamily="heading"
            fontSize={{ base: "2xl", md: "4xl" }}
            textAlign="center"
            letterSpacing="tight"
            mb="8"
          >
            Frequently asked questions
          </Heading>
          <Accordion.Root collapsible defaultValue={[faq[0].q]}>
            {faq.map((item) => (
              <Accordion.Item key={item.q} value={item.q}>
                <Accordion.ItemTrigger>
                  <Span flex="1" fontWeight="medium">
                    {item.q}
                  </Span>
                  <Accordion.ItemIndicator />
                </Accordion.ItemTrigger>
                <Accordion.ItemContent>
                  <Accordion.ItemBody color="fg.muted">
                    {item.a}
                  </Accordion.ItemBody>
                </Accordion.ItemContent>
              </Accordion.Item>
            ))}
          </Accordion.Root>
        </Container>
      </Box>
    </>
  )
}
